const r = $input.first().json;
const results = r.results || [];
return [{ json: {
  skipped: r.skipped || null,
  claimed: r.claimed || 0,
  drafted: results.filter(x => x.status === 'drafted').length,
  approved: results.filter(x => x.status === 'approved').length,
  failed: results.filter(x => x.status === 'failed').length,
  cost_usd: results.reduce((a, x) => a + (x.cost_usd || 0), 0),
  error: r.error || null,
} }];
